// Paint colors by medium and brand line, from artistpigments.org (CC BY-NC 4.0), generated by
// scripts/artistpigments-paints.py. About 200 KB, so the Palettes tab loads it on demand.

import type { PaletteColor } from '../shared/types';

/** A paint: name, sRGB hex, pigment codes (space-separated), and 1 when discontinued. */
export type LibraryPaint = [name: string, hex: string, pigments: string, discontinued?: 1];

export interface LibraryLine {
  id: string;
  name: string;
  /** The brand in a few words, for color names. */
  short: string;
  paints: LibraryPaint[];
}

export interface LibraryMedium {
  id: string;
  name: string;
  brands: LibraryLine[];
}

export interface PaintLibrary {
  source: string;
  license: string;
  retrieved: string;
  media: LibraryMedium[];
}

let loading: Promise<PaintLibrary> | null = null;

export function loadPaintLibrary(): Promise<PaintLibrary> {
  loading ??= import('./paint-library.json').then((m) => m.default as unknown as PaintLibrary);
  return loading;
}

/** A library paint as a palette color, named "<paint> (<brand>)". */
export function paintColor(p: LibraryPaint, line: LibraryLine): PaletteColor {
  return { hex: p[1], name: `${p[0]} (${line.short})` };
}

/** The line under the buttons for a library paint: name, line, pigments, discontinued. */
export function paintDetail(p: LibraryPaint, line: LibraryLine): string {
  return [p[0], line.name, p[2], p[3] ? 'discontinued' : ''].filter(Boolean).join(' · ');
}
